use anyhow::{Result,ensure};use glam::Mat4;use std::time::{Instant,Duration};
use crate::{Prepared,gpu::Gpu,scene::Scene,hud::Hud,hud_stream::{HudStream,HudCost},log::{Log,root}};
pub fn run(log:&Log,prepared:Prepared)->Result<()>{let finish=std::env::args().any(|a|a=="--ui-finish-hud-validate");let layout=finish||std::env::args().any(|a|a=="--layout-hud-validate");let mut gpu=Gpu::new(log,None,0xb000)?;let mut scene=Scene::new(prepared.source,prepared.assets,&mut gpu)?;scene.seek(24600.0);scene.elapsed_seconds=12.0;scene.hud_scale=0.8;let(head,q,view)=crate::capture::camera(0.0,42.0,3.7);for _ in 0..12{scene.update(&mut gpu,head,q,0.1)?;}let mut direct=Hud::new(&scene.assets.portraits)?;let mut worker=HudStream::new(&scene.assets.portraits,false)?;let(texture,target)=gpu.offscreen(1600,1100)?;let vp=if layout{let mesh=crate::geometry::mesh("validationHudAtlas",crate::geometry::quad(),vec![crate::geometry::Instance::new(Mat4::from_scale(glam::Vec3::new(1.0,1.25,1.0)),[0.0,0.0,1.0,1.0],[1.0;4],[10.0,0.001,0.0,0.0])],true,false);gpu.add_mesh(&mesh,1)?;gpu.mask(|n|n=="validationHudAtlas");Mat4::orthographic_rh(-0.5,0.5,-0.625,0.625,0.01,10.0)*Mat4::look_at_rh(glam::Vec3::new(0.0,0.0,2.0),glam::Vec3::ZERO,glam::Vec3::Y)}else{gpu.mask(|n|n=="hud");Mat4::perspective_rh(42f32.to_radians(),1600.0/1100.0,0.01,40.0)*view};let first=scene.hud_content();let mut previous=first;let mut cases=Vec::new();
 for i in 0..3{let mut content=first;if i==1{content.tick+=60.0;content.scores[0]+=1;content.health[0][0]=0.0;content.health[1][1]=0.42;content.show_intro=true;content.adjustment=Some((1.2,0.88,1.4,90.0));}else if i==2{content.tick+=120.0;content.health[0][0]=0.8;content.health[1][1]=0.1;}
  if layout{if i==1{content.combat.players[0][2].cooldowns[1]=7;content.combat.players[0][2].cooldown_mask=6;content.combat.feed=[crate::hud::FeedEntry{tick:24600,kind:0,team:0,killer:2,victim:2,assists:0},Default::default(),Default::default()];content.combat.feed_width=198;}else if i==2{content.combat.players[0][2].cooldowns[1]=0;content.combat.feed=[Default::default();3];content.combat.feed_width=0;}}
  gpu.update_hud(direct.render(&content))?;gpu.render(&target,vp,scene.world(),true);let(_,_,expected)=gpu.pixels(&texture)?;gpu.update_hud(direct.render(&previous))?;let start=Instant::now();let mut cost=worker.update(&gpu,Some(content))?;while !cost.updated&&start.elapsed()<Duration::from_secs(5){std::thread::sleep(Duration::from_millis(1));cost=worker.update(&gpu,None)?;}ensure!(cost.updated,"HUD 준비 스레드 결과 시간 제한");gpu.render(&target,vp,scene.world(),true);let(_,_,actual)=gpu.pixels(&texture)?;let differences=actual.iter().zip(&expected).filter(|(a,b)|a!=b).count();ensure!(differences==0,"HUD 동기/비동기 GPU 픽셀 차이 {differences}");gpu.save_png(&texture,&root().join(format!("_tmp/shots/{}_case_{i}.png",if finish{"native_ui_finish_hud"}else if layout{"native_ui_layout_hud"}else{"native_hud_pipeline"})))?;cases.push(serde_json::json!({"case":i,"changedBytes":differences,"uploadedBytes":cost.bytes,"mainMs":cost.total,"workerMs":[cost.worker_render,cost.worker_pack,cost.worker_diff]}));previous=content;
 }let report=serde_json::json!({"검증":"통과","cases":cases,"입력":"별도검증에서만 점수/체력/안내/조절값·쿨다운칸·킬피드폭/행수를 바꾼 합성입력 · 실제 경기 수치 아님","전체캔버스비교":layout,"방법":"동기 전체업로드 기대GPU픽셀 대 이전 상태 복원 후 비동기 부분업로드 GPU픽셀, 정확 비교","실기기":"세션 미실행"});std::fs::write(root().join(if finish{"_tmp/logs/native_ui_finish_hud_validation.json"}else if layout{"_tmp/logs/native_ui_layout_hud_validation.json"}else{"_tmp/logs/native_hud_pipeline_validation.json"}),serde_json::to_vec_pretty(&report)?)?;log.line("동기/비동기 HUD 픽셀·부분영역·안내접힘·사망초상 복원 검사 통과");Ok(())}
